/bin/zsh -lc "node --input-type=module <<'NODE'
import assert from 'node:assert/strict';
import runQueue, { readLimit } from './dist/queue.js';
import { submit } from './dist/caller.js';
const job = (id, priority = 1) => ({ id, priority });
assert.equal(readLimit('0'), 3);
let pausedSaves = 0;
const status = await submit([job('paused')], async () => { pausedSaves++; });
assert.equal(pausedSaves, 1);
console.log('PAUSE: readLimit(\"0\") = 3; submit starts 1 save and returns', status);
const jobs = [job('a', 3), job('b', 1), job('c', 2)];
const saveOrder = [];
await runQueue(jobs, '2', async j => { saveOrder.push(j.id); });
assert.deepEqual(jobs.map(j => j.id), ['b', 'c', 'a']);
assert.deepEqual(saveOrder, ['b', 'c']);
console.log('OWNERSHIP: input [a,b,c] becomes', JSON.stringify(jobs.map(j => j.id)));
const allOrder = [];
await runQueue([job('a', 2), job('b', 1)], '2', async j => { allOrder.push(j.id); });
assert.deepEqual(allOrder, ['b', 'a']);
console.log('ORDER: both jobs selected; input [a,b], save starts', JSON.stringify(allOrder));
let release;
const gate = new Promise(resolve => { release = resolve; });
const started = [], completed = [];
await runQueue([job('first'), job('second', 2)], '2', async j => {
  started.push(j.id);
  await gate;
  completed.push(j.id);
});
assert.deepEqual(started, ['first', 'second']);
assert.deepEqual(completed, []);
console.log('AWAIT/SEQUENCE: queue resolved with started =', JSON.stringify(started), 'completed =', JSON.stringify(completed));
release();
await new Promise(resolve => setImmediate(resolve));
const failure = new Error('save failed');
const unhandled = [];
const listener = error => unhandled.push(error);
process.on('unhandledRejection', listener);
const failureStarts = [];
let queueRejected = false;
try {
  await runQueue([job('first'), job('second', 2)], '2', async j => {
    failureStarts.push(j.id);
    if (j.id === 'first') throw failure;
  });
} catch { queueRejected = true; }
await new Promise(resolve => setImmediate(resolve));
process.off('unhandledRejection', listener);
assert.equal(queueRejected, false);
assert.deepEqual(failureStarts, ['first', 'second']);
assert.deepEqual(unhandled, [failure]);
console.log('FAILURE: queue rejected =', queueRejected, '; starts =', JSON.stringify(failureStarts), '; unhandled rejection =', unhandled[0].message);
console.log('All reproduction assertions passed (assertions confirm defects).');
NODE"

